import base64
import zipfile
import io
import json
import structlog

log = structlog.get_logger()

# Base64 encoded contents of digitaltraffic-detectai.skill
SKILL_B64 = ""

_PROMPT_CACHE = None

def get_humanizer_prompt() -> str:
    global _PROMPT_CACHE
    if _PROMPT_CACHE:
        return _PROMPT_CACHE
    
    try:
        zip_data = base64.b64decode(SKILL_B64)
        with zipfile.ZipFile(io.BytesIO(zip_data)) as z:
            for name in z.namelist():
                # The file is expected to be digitaltraffic-detectai/digitaltraffic-detectai.skill inside the zip
                if name.endswith(".skill") or name.endswith(".md") or name.endswith(".txt"):
                    data = z.read(name).decode("utf-8")
                    # Claude skill format is a JSON with a 'prompt' field, or just raw text depending on export.
                    try:
                        parsed = json.loads(data)
                        if "prompt" in parsed:
                            _PROMPT_CACHE = parsed["prompt"]
                            return _PROMPT_CACHE
                    except json.JSONDecodeError:
                        # If not JSON, return the raw text
                        _PROMPT_CACHE = data
                        return _PROMPT_CACHE
        return "You are an expert editor. Make this text sound human."
    except Exception as e:
        log.error("humanizer_prompt_extract_error", error=str(e))
        return "Error extracting humanizer prompt."
